/* From Uiverse.io by alexruix - Tags: material design, input */
.__UIV_SCOPE__ .input-group {
 position: relative;
}

.__UIV_SCOPE__ .input {
 border: solid 1.5px #9e9e9e;
 border-radius: 1rem;
 background: none;
 padding: 1rem;
 font-size: 1rem;
 color: #f5f5f5;
 transition: border 150ms cubic-bezier(0.4,0,0.2,1);
}

.__UIV_SCOPE__ .user-label {
 position: absolute;
 left: 15px;
 color: #e8e8e8;
 pointer-events: none;
 transform: translateY(1rem);
 transition: 150ms cubic-bezier(0.4,0,0.2,1);
}

.__UIV_SCOPE__ .input:focus, .__UIV_SCOPE__ input:valid {
 outline: none;
 border: 1.5px solid #1a73e8;
}

.__UIV_SCOPE__ .input:focus ~ label, .__UIV_SCOPE__ input:valid ~ label {
 transform: translateY(-50%) scale(0.8);
 background-color: #212121;
 padding: 0 .2em;
 color: #2196f3;
}
